    const desc = document.createElement("div");
    desc.id = "bipa-consent-description";
    desc.style.fontSize = "0.9rem";
    desc.style.lineHeight = "1.55";
    desc.style.color = "#a1a1aa";
    desc.style.marginTop = "12px";

