    p2.style.fontSize = "0.78rem";
    p2.style.color = "#71717a";
    p2.style.marginTop = "8px";
    p2.textContent = `Policy Version: ${POLICY_VERSION} | Contact: privacy@ar-trion.internal`;
    desc.appendChild(checkboxContainer);
    desc.appendChild(p2);

    const actions = document.createElement("div");
    actions.className = "bipa-consent-actions";
    actions.style.display = "flex";
    actions.style.justifyContent = "flex-end";
    actions.style.gap = "12px";
    actions.style.marginTop = "20px";

    const declineBtn = document.createElement("button");
    declineBtn.id = "bipa-btn-decline";
    declineBtn.type = "button";
    declineBtn.style.padding = "10px 16px";
    declineBtn.style.border = "1px solid #3f3f46";
    declineBtn.style.background = "transparent";
    declineBtn.style.color = "#a1a1aa";
    declineBtn.style.borderRadius = "8px";
    declineBtn.style.cursor = "pointer";
    declineBtn.style.fontWeight = "600";
    declineBtn.style.fontSize = "0.88rem";
    declineBtn.textContent = "Decline";

    const acceptBtn = document.createElement("button");
    acceptBtn.id = "bipa-consent-submit";
    acceptBtn.type = "button";
    acceptBtn.disabled = true;
    acceptBtn.style.padding = "10px 20px";
    acceptBtn.style.border = "none";
    acceptBtn.style.background = "#ec4899";
    acceptBtn.style.color = "#ffffff";
    acceptBtn.style.borderRadius = "8px";
    acceptBtn.style.cursor = "pointer";
    acceptBtn.style.fontWeight = "600";
    acceptBtn.style.fontSize = "0.88rem";
    acceptBtn.style.opacity = "0.5";
    acceptBtn.style.transition = "all 0.2s ease";
    acceptBtn.textContent = "Enable Camera";

    checkbox.addEventListener("change", () => {
      acceptBtn.disabled = !checkbox.checked;
      acceptBtn.style.opacity = checkbox.checked ? "1" : "0.5";
      acceptBtn.style.cursor = checkbox.checked ? "pointer" : "not-allowed";
    });

    actions.appendChild(declineBtn);
    actions.appendChild(acceptBtn);

    card.appendChild(title);
    card.appendChild(desc);
    card.appendChild(actions);
    overlay.appendChild(card);

    acceptBtn.addEventListener("click", async () => {
      if (acceptBtn.disabled) return;
      const actor = this.options.actor || "anonymous-browser-user";
      const record = await grantClickwrapConsent(this.options.store, actor);
      if (this.options.consentInstance) {
        this.options.consentInstance.grantConsent();
      }
      overlay.remove();
      this.options.onConsentGranted?.(record);
    });

    declineBtn.addEventListener("click", async () => {
      const actor = this.options.actor || "anonymous-browser-user";
      if (this.options.consentInstance) {
        this.options.consentInstance.revokeConsent();
      }
      await revokeClickwrapConsent(this.options.store, actor);
      overlay.remove();
      this.options.onConsentDeclined?.();
    });

    this.containerElement = overlay;
    return overlay;
  }

  public destroy(): void {
    if (this.containerElement) {
      this.containerElement.remove();
      this.containerElement = null;
    }
  }
}

import {
  HandLandmarker,
  FilesetResolver,
  HandLandmarkerResult
} from '@mediapipe/tasks-vision';

export interface HandTrackerOptions {
  wasmPath?: string;
  modelAssetPath?: string;
  numHands?: number;
  minHandDetectionConfidence?: number;
  minHandPresenceConfidence?: number;
  minTrackingConfidence?: number;
}

export class HandTracker {
  private handLandmarker: HandLandmarker | null = null;
  private isInitialized: boolean = false;
  private isClosed: boolean = false;

  public async initialize(options: HandTrackerOptions = {}): Promise<void> {
    this.isClosed = false;

    const wasmLoaderPath = options.wasmPath || '/wasm';
    const modelPath = options.modelAssetPath || '/models/hand_landmarker.task';

    if (wasmLoaderPath.startsWith('http://') || wasmLoaderPath.startsWith('https://')) {
      throw new Error(`Zero-Egress Violation: Remote Wasm URL "${wasmLoaderPath}" rejected. Must use local offline bundled path.`);
    }

    if (modelPath.startsWith('http://') || modelPath.startsWith('https://')) {
      throw new Error(`Zero-Egress Violation: Remote model URL "${modelPath}" rejected. Must use local offline bundled path.`);
    }

    const vision = await FilesetResolver.forVisionTasks(wasmLoaderPath);

    if (this.isClosed) {
      return;
    }

    const landmarker = await HandLandmarker.createFromOptions(vision, {
      baseOptions: {
        modelAssetPath: modelPath,
        delegate: 'GPU'
      },
      runningMode: 'VIDEO',
      numHands: options.numHands || 1,
      minHandDetectionConfidence: options.minHandDetectionConfidence ?? 0.7,
      minHandPresenceConfidence: options.minHandPresenceConfidence ?? 0.5,
      minTrackingConfidence: options.minTrackingConfidence ?? 0.5
    });

    if (this.isClosed) {
      landmarker.close();
      return;
    }

    this.handLandmarker = landmarker;
    this.isInitialized = true;
  }

  public detectForVideo(videoFrame: HTMLVideoElement | HTMLCanvasElement, timestampMs: number): HandLandmarkerResult | null {
    if (this.isClosed || !this.isInitialized || !this.handLandmarker) {
      return null;
    }
    if (typeof HTMLVideoElement !== 'undefined' && videoFrame instanceof HTMLVideoElement) {
      if (videoFrame.readyState < 2 || videoFrame.videoWidth === 0 || videoFrame.videoHeight === 0) {
        return null;
      }
    }
    return this.handLandmarker.detectForVideo(videoFrame, timestampMs);
  }

  public close(): void {
    this.isClosed = true;
    if (this.handLandmarker) {
      this.handLandmarker.close();
      this.handLandmarker = null;
    }
    this.isInitialized = false;
  }
}

export interface Point3D {
  x: number;
  y: number;
  z: number;
}

export interface NailTransform {
  finger: 'thumb' | 'index' | 'middle' | 'ring' | 'pinky';
  center: Point3D;
  normal: Point3D;
  scale: Point3D;
  dipIndex: number;
  tipIndex: number;
}

export class NailExtractor {
  public static readonly DISTAL_PHALANGES = [
    { finger: 'thumb' as const, dip: 3, tip: 4 },
    { finger: 'index' as const, dip: 7, tip: 8 },
    { finger: 'middle' as const, dip: 11, tip: 12 },
    { finger: 'ring' as const, dip: 15, tip: 16 },
    { finger: 'pinky' as const, dip: 19, tip: 20 }
  ];

  private static readonly REUSABLE_TRANSFORMS: NailTransform[] = NailExtractor.DISTAL_PHALANGES.map(phalanx => ({
    finger: phalanx.finger,
    center: { x: 0, y: 0, z: 0 },
    normal: { x: 0, y: 0, z: 1 },
    scale: { x: 0, y: 0, z: 0 },
    dipIndex: phalanx.dip,
    tipIndex: phalanx.tip
  }));

  private static readonly EMPTY_RESULT: NailTransform[] = [];

  public extractNails(landmarks: Point3D[]): NailTransform[] {
    if (!landmarks || landmarks.length < 21) {
      return NailExtractor.EMPTY_RESULT;
    }

    const wrist = landmarks[0];

    for (let i = 0; i < NailExtractor.DISTAL_PHALANGES.length; i++) {
      const phalanx = NailExtractor.DISTAL_PHALANGES[i];
      const target = NailExtractor.REUSABLE_TRANSFORMS[i];
      const dip = landmarks[phalanx.dip];
      const tip = landmarks[phalanx.tip];

      target.center.x = dip.x * 0.35 + tip.x * 0.65;
      target.center.y = dip.y * 0.35 + tip.y * 0.65;
      target.center.z = dip.z * 0.35 + tip.z * 0.65;

      const dirX = tip.x - dip.x;
      const dirY = tip.y - dip.y;
      const dirZ = tip.z - dip.z;
      const length = Math.sqrt(dirX * dirX + dirY * dirY + dirZ * dirZ) || 0.001;

      const wristX = dip.x - wrist.x;
      const wristY = dip.y - wrist.y;
      const wristZ = dip.z - wrist.z;

      const normX = dirY * wristZ - dirZ * wristY;
      const normY = dirZ * wristX - dirX * wristZ;
      const normZ = dirX * wristY - dirY * wristX;
      const normLen = Math.sqrt(normX * normX + normY * normY + normZ * normZ);

      if (normLen > 1e-6) {
        target.normal.x = normX / normLen;
        target.normal.y = normY / normLen;
        target.normal.z = normZ / normLen;
      } else {
        target.normal.x = 0;
        target.normal.y = 0;
        target.normal.z = 1;
      }

      target.scale.x = length * 0.45;
      target.scale.y = length * 0.65;
      target.scale.z = length * 0.2;
    }

    return NailExtractor.REUSABLE_TRANSFORMS;
  }
}

import { Point3D, NailTransform } from '../mediapipe/NailExtractor';

export interface OcclusionConfig {
  curlDistanceThreshold?: number;
  zDepthTolerance?: number;
}

export class OcclusionMask {
  private curlThreshold: number;
  private zTolerance: number;

  constructor(config: OcclusionConfig = {}) {
    this.curlThreshold = config.curlDistanceThreshold ?? 0.85;
    this.zTolerance = config.zDepthTolerance ?? 0.05;
  }

  public evaluateOcclusion(
    landmarks: Point3D[],
    nails: NailTransform[]
  ): Map<string, boolean> {
    const occlusionResults = new Map<string, boolean>();

    if (!landmarks || landmarks.length < 21) {
      for (const nail of nails) {
        occlusionResults.set(nail.finger, true);
      }
      return occlusionResults;
    }

    const wrist = landmarks[0];
    const middleMCP = landmarks[9];

    for (const nail of nails) {
      const tip = landmarks[nail.tipIndex];
      const dip = landmarks[nail.dipIndex];

      const tipToWrist = this.distance3D(tip, wrist);
      const dipToWrist = this.distance3D(dip, wrist);

      const isCurled = tipToWrist < dipToWrist * this.curlThreshold;
      const isBehindPalm = (tip.z - middleMCP.z) > this.zTolerance;

      const isOccluded = isCurled || isBehindPalm;
      occlusionResults.set(nail.finger, isOccluded);
    }

    return occlusionResults;
  }

  private distance3D(p1: Point3D, p2: Point3D): number {
    const dx = p1.x - p2.x;
    const dy = p1.y - p2.y;
    const dz = p1.z - p2.z;
    return Math.sqrt(dx * dx + dy * dy + dz * dz);
  }
}

import * as ort from 'onnxruntime-web';

export interface LightingEstimate {
  directionalLightVector: [number, number, number];
  lightIntensity: number;
  environmentMapData: Float32Array;
  inferenceTimeMs: number;
}

export class LightingEstimator {
  private session: ort.InferenceSession | null = null;
  private isInitialized: boolean = false;
  private isClosed: boolean = false;
  private offscreenCanvas: OffscreenCanvas | HTMLCanvasElement | null = null;
  private ctx: OffscreenCanvasRenderingContext2D | CanvasRenderingContext2D | null = null;

  public async initialize(modelPath?: string): Promise<void> {
    this.isClosed = false;

    if (modelPath && (modelPath.startsWith('http://') || modelPath.startsWith('https://'))) {
      throw new Error(`Zero-Egress Violation: Remote lighting model URL "${modelPath}" rejected. Must use local offline bundled path.`);
    }

    try {
      if (modelPath) {
        const session = await ort.InferenceSession.create(modelPath, {
          executionProviders: ['webgl', 'wasm']
        });

        if (this.isClosed) {
          session.release();
          return;
        }

        this.session = session;
      }
      this.isInitialized = true;
    } catch (e) {
      console.warn('LightingEstimator: ONNX model loading fallback to synthetic EnvMapNet heuristic.', e);
      if (!this.isClosed) {
        this.isInitialized = true;
      }
    }
  }

  public async estimateLighting(
    frame: HTMLVideoElement | HTMLCanvasElement | ImageBitmap | ImageData
  ): Promise<LightingEstimate> {
    const startTime = performance.now();

    const downsampledWidth = 64;
    const downsampledHeight = 64;

    const pixelData = this.extractPixelData(frame, downsampledWidth, downsampledHeight);

    const envMapData = new Float32Array(downsampledWidth * downsampledHeight * 3);
    const inputTensorData = new Float32Array(1 * 3 * downsampledWidth * downsampledHeight);

    let totalLuminance = 0;
    let maxLum = 0;
    let brightestX = downsampledWidth / 2;
    let brightestY = downsampledHeight / 2;

    for (let y = 0; y < downsampledHeight; y++) {
      for (let x = 0; x < downsampledWidth; x++) {
        const pixelIdx = (y * downsampledWidth + x) * 4;
        const r = (pixelData ? pixelData[pixelIdx] : 128) / 255;
        const g = (pixelData ? pixelData[pixelIdx + 1] : 128) / 255;
        const b = (pixelData ? pixelData[pixelIdx + 2] : 128) / 255;

        const planeSize = downsampledWidth * downsampledHeight;
        const hwIdx = y * downsampledWidth + x;
        inputTensorData[hwIdx] = r;
        inputTensorData[planeSize + hwIdx] = g;
        inputTensorData[2 * planeSize + hwIdx] = b;

        envMapData[hwIdx * 3] = r;
        envMapData[hwIdx * 3 + 1] = g;
        envMapData[hwIdx * 3 + 2] = b;

        const lum = 0.2126 * r + 0.7152 * g + 0.0722 * b;
        totalLuminance += lum;
        if (lum > maxLum) {
          maxLum = lum;
          brightestX = x;
          brightestY = y;
        }
      }
    }

    const avgLuminance = totalLuminance / (downsampledWidth * downsampledHeight);
    let lightIntensity = Math.min(Math.max(avgLuminance * 2.0, 0.2), 2.0);

    let lightVector: [number, number, number] = [0.577, 0.577, 0.577];

    if (!this.isClosed && this.session) {
      try {
        const inputTensor = new ort.Tensor('float32', inputTensorData, [1, 3, downsampledWidth, downsampledHeight]);
        const feeds: Record<string, ort.Tensor> = {};
        feeds[this.session.inputNames[0]] = inputTensor;
        const results = await this.session.run(feeds);
        const output = results[this.session.outputNames[0]];
        if (output && output.data) {
          const data = output.data as Float32Array;
          lightVector = [data[0] || 0.577, data[1] || 0.577, data[2] || 0.577];
        }
      } catch (err) {
        lightVector = this.deriveVectorFromBrightestPixel(brightestX, brightestY, downsampledWidth, downsampledHeight);
      }
    } else {
      lightVector = this.deriveVectorFromBrightestPixel(brightestX, brightestY, downsampledWidth, downsampledHeight);
    }

    const len = Math.sqrt(lightVector[0] ** 2 + lightVector[1] ** 2 + lightVector[2] ** 2) || 1;
    const normalizedVector: [number, number, number] = [
      lightVector[0] / len,
      lightVector[1] / len,
      lightVector[2] / len
    ];

    const inferenceTimeMs = performance.now() - startTime;

    return {
      directionalLightVector: normalizedVector,
      lightIntensity,
      environmentMapData: envMapData,
      inferenceTimeMs
    };
  }

  private deriveVectorFromBrightestPixel(
    brightestX: number,
    brightestY: number,
    width: number,
    height: number
  ): [number, number, number] {
    const nx = (brightestX / width) * 2 - 1;
    const ny = -((brightestY / height) * 2 - 1);
    const nz = 1.0;
    return [nx, ny, nz];
  }

  private extractPixelData(
    frame: HTMLVideoElement | HTMLCanvasElement | ImageBitmap | ImageData,
    width: number,
    height: number
  ): Uint8ClampedArray | Uint8Array | null {
    if (typeof ImageData !== 'undefined' && frame instanceof ImageData) {
      return frame.data;
    }

    try {
      if (typeof OffscreenCanvas !== 'undefined') {
        if (!this.offscreenCanvas) {
          this.offscreenCanvas = new OffscreenCanvas(width, height);
          this.ctx = this.offscreenCanvas.getContext('2d', { willReadFrequently: true }) as OffscreenCanvasRenderingContext2D;
        }
      } else if (typeof document !== 'undefined') {
        if (!this.offscreenCanvas) {
          const canvas = document.createElement('canvas');
          canvas.width = width;
          canvas.height = height;
          this.offscreenCanvas = canvas;
          this.ctx = canvas.getContext('2d', { willReadFrequently: true });
        }
      }

      if (this.ctx) {
        this.ctx.drawImage(frame as CanvasImageSource, 0, 0, width, height);
        return this.ctx.getImageData(0, 0, width, height).data;
      }
    } catch (e) {
      // Fallback
    }
    return null;
  }

  public close(): void {
    this.isClosed = true;
    if (this.session) {
      this.session.release();
      this.session = null;
    }
    this.offscreenCanvas = null;
    this.ctx = null;
    this.isInitialized = false;
  }
}

import { NetworkEgressGuard } from "./NetworkEgressGuard";

export type AllowedRuntime = "onnxruntime-web" | "litert" | "@xenova/transformers";

export interface LocalRuntimeConfig {
  runtime: AllowedRuntime;
  localModelPath: string;
  executionProvider?: "webgpu" | "wasm" | "cpu";
  allowRemoteModelDownload?: boolean;
}

export interface InferenceGeometryResult {
  landmarks: Float32Array[];
  handedness: "left" | "right" | "unknown";
  confidence: number;
}

export class LocalInferenceRuntime {
  private config: LocalRuntimeConfig;
  private isInitialized = false;

  constructor(config: LocalRuntimeConfig) {
    if (config.allowRemoteModelDownload) {
      throw new Error(
        "Edge Security Violation: allowRemoteModelDownload must be false. Models must be bundled locally."
      );
    }

    if (config.localModelPath.startsWith("http://") || config.localModelPath.startsWith("https://")) {
      NetworkEgressGuard.recordViolation(config.localModelPath, "GET");
      throw new Error(
        `Edge Security Violation: Remote model URL "${config.localModelPath}" rejected. Only local offline bundled paths are permitted.`
      );
    }

    this.config = config;
  }

  public async initialize(): Promise<void> {
    NetworkEgressGuard.activate();
    this.isInitialized = true;
  }

  public async inferGeometry(inputBuffer: Uint8ClampedArray): Promise<InferenceGeometryResult> {
    if (!this.isInitialized) {
      throw new Error("LocalInferenceRuntime must be initialized before processing frames.");
    }

    // Local edge processing simulator adhering to 21 hand landmarks (x, y, z)
    const landmarks: Float32Array[] = [];
    for (let i = 0; i < 21; i++) {
      const landmark = new Float32Array(3);
      landmark[0] = 0.5 + (i * 0.01);
      landmark[1] = 0.5 + (i * 0.01);
      landmark[2] = 0.0;
      landmarks.push(landmark);
    }

    return {
      landmarks,
      handedness: "right",
      confidence: 0.98
    };
  }

  public getRuntime(): AllowedRuntime {
    return this.config.runtime;
  }

  public isReady(): boolean {
    return this.isInitialized;
  }
}

